import type { DesktopItem } from '@/types';

/**
 * 内置默认桌面的图标资源（base64 dataURL 分片存储）。
 * 单独拆分到此文件，避免桌面布局模块因体积过大影响可读性。
 */
export const BUILTIN_ICON_ASSETS: Record<string, string> = {
  "id_1784021229944_5mwmct": 'data:image/webp;base64,',
  "id_1794192239547_k7uftc": 'data:image/webp;base64,',
  "id_1785131053839_m2t248": 'data:image/webp;base64,',
  "id_1784451858769_nqqyzf": 'data:image/webp;base64,',
  "id_1784638854574_c1zloc": 'data:image/webp;base64,',
  "id_1784451479354_my103l": 'data:image/webp;base64,',
  "id_1784638886262_p0uddx": 'data:image/webp;base64,',
  "id_1784777048635_4wx602": 'data:image/webp;base64,',
  "id_1786108696922_h1tet8": 'data:image/webp;base64,',
  "sys-sync": 'data:image/webp;base64,',
  "id_1785406850521_o41gc6": 'data:image/webp;base64,',
  "id_1784801261722_onaish": 'data:image/webp;base64,',
  "id_1783909726432_nze6mj": 'data:image/webp;base64,',
  "id_1785122264303_5312up": 'data:image/webp;base64,',
};

/** 将内置布局中的图标占位符替换为真实 dataURL。 */
export function resolveBuiltinIcons(items: DesktopItem[]): DesktopItem[] {
  return items.map((item) => {
    const next: DesktopItem = { ...item };
    const icon = next.iconUrl;
    if (icon && icon.startsWith('@@ICON@@')) {
      const id = icon.slice(8, -2);
      const asset = BUILTIN_ICON_ASSETS[id];
      if (asset) next.iconUrl = asset;
    }
    if (next.children) next.children = resolveBuiltinIcons(next.children);
    return next;
  });
}
